#pragma once
static void testHostedPdc(const juce::File& root){
 auto base=root.getChildFile("pdc-hosted");base.createDirectory();juce::Array<juce::var> cases;
 for(int block:{128,256})for(bool send:{false,true}){
  auto dir=base.getChildFile(juce::String(block)+(send?"-send":"-parallel"));dir.createDirectory();Session s(dir);s.edit.reset();auto& hosted=s.engine.getDeviceManager().getHostedAudioDeviceInterface();te::HostedAudioDeviceInterface::Parameters params;params.sampleRate=48000;params.blockSize=block;params.inputChannels=0;params.outputChannels=2;hosted.initialise(params);hosted.prepareToPlay(48000,block);
  te::Edit::Options options{s.engine,te::createEmptyEdit(s.engine),te::ProjectItemID::createNewID(0)};options.role=te::Edit::forEditing;options.numAudioTracks=0;options.defaultMasterVolumedB=0;options.editFileRetriever=[&s]{return s.projectFile;};s.edit=std::make_unique<te::Edit>(options);
  auto source=dir.getChildFile("impulses.wav");juce::AudioBuffer<float> input(2,48000);input.clear();for(int c=0;c<2;++c){input.setSample(c,12000,0.001f);input.setSample(c,36000,0.001f);}juce::WavAudioFormat wav;std::unique_ptr<juce::AudioFormatWriter> writer(wav.createWriterFor(source.createOutputStream().release(),48000,2,32,{},0));require(writer&&writer->writeFromAudioSampleBuffer(input,0,48000),"Hosted PDC source failed");writer.reset();s.importAudio(source,0,0);s.importAudio(source,1,0);
  juce::VST3PluginFormat format;juce::OwnedArray<juce::PluginDescription> types;format.findAllTypesForFile(types,juce::File(STUDIO_SOURCE_ROOT).getChildFile("build/backend/StudioTestDelay_artefacts/Release/VST3/Studio Test Delay.vst3").getFullPathName());require(types.size()==1,"Hosted delay missing");auto& effect=PluginChain::add(s,1,*types[0]);
  if(send){auto bus=s.addBus();s.addSend(0,bus,0,true);auto& ret=PluginChain::add(s,bus,*types[0]);ret.getAudioPluginInstance()->getParameters()[1]->setValueNotifyingHost(511.0f/4096);ret.flushPluginStateToValueTree();}
  juce::AudioBuffer<float> audio(2,block),captured(2,50000+block);captured.clear();juce::MidiBuffer midi;
  for(int n=0;n<10;++n){audio.clear();midi.clear();hosted.processBlock(audio,midi);juce::MessageManager::getInstance()->runDispatchLoopUntil(1);}
  auto& transport=s.edit->getTransport();transport.setPosition(Session::time(0));transport.play(false);bool changed=false;
  for(int at=0;at+block<=captured.getNumSamples();at+=block){if(at>=16000&&!changed){effect.getAudioPluginInstance()->getParameters()[1]->setValueNotifyingHost(4096.0f/4096);changed=true;}audio.clear();midi.clear();hosted.processBlock(audio,midi);for(int c=0;c<2;++c)captured.copyFrom(c,at,audio,c,0,block);juce::MessageManager::getInstance()->runDispatchLoopUntil(1);}
  transport.stop(false,true);float expected=send?0.003f:0.002f;juce::Array<juce::var> peaks;
  for(int wanted:{12000,36000}){int peak=-1;float magnitude=0;for(int i=wanted-8192;i<wanted+8192;++i)if(std::abs(captured.getSample(0,i))>magnitude){magnitude=std::abs(captured.getSample(0,i));peak=i;}peaks.add(peak);dir.getChildFile("peaks.txt").appendText(juce::String(wanted)+" -> "+juce::String(peak)+" level "+juce::String(magnitude,9)+"\n");require(std::abs(magnitude-expected)<1e-6f,"Hosted dynamic PDC split impulse");int reported=wanted==12000?(send?511:257):4096;require(std::abs(peak-wanted-reported)<=block*2,"Hosted dynamic PDC latency-adjusted shift exceeds bound");int count=0;for(int i=wanted-8192;i<wanted+8192;++i)if(std::abs(captured.getSample(0,i))>1e-6f)++count;require(count==1,"Hosted dynamic PDC has unaligned copies");}
  require(effect.getAudioPluginInstance()->getLatencySamples()==4096,"Hosted latency change not reported");auto* device=s.engine.getDeviceManager().deviceManager.getCurrentAudioDevice();require(device&&device->getTypeName()=="Hosted Device","Hosted PDC used a physical device");auto* result=new juce::DynamicObject;result->setProperty("block",block);result->setProperty("pre_fader_send",send);result->setProperty("peak_samples",peaks);result->setProperty("changed_during_playback",changed);result->setProperty("reported_latency",4096);cases.add(juce::var(result));
 }
 auto* report=new juce::DynamicObject;report->setProperty("checks",cases.size());report->setProperty("cases",cases);report->setProperty("physical_device_opened",false);base.getChildFile("pdc-hosted-result.json").replaceWithText(juce::JSON::toString(juce::var(report)));
}
